<?php
namespace App\Http\Controllers;
use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Spatie\Permission\Models\Role; use Spatie\Permission\Models\Permission; use App\Support\Activity;
class UserController extends Controller {
 public function index(){ $users=User::with('roles')->latest()->paginate(15);return view('users.index',compact('users')); }
 public function create(){return view('users.form',['user'=>new User,'roles'=>Role::where('name','!=','Super Admin')->get(),'permissions'=>Permission::orderBy('name')->get()]);}
 public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:190','email'=>'required|email|unique:users,email','password'=>'required|string|min:10|confirmed','role'=>'required|exists:roles,name','permission_ids'=>'nullable|array','permission_ids.*'=>'exists:permissions,id']);$u=User::create(['name'=>$d['name'],'email'=>$d['email'],'password'=>Hash::make($d['password'])]);$u->assignRole($d['role']);$u->syncPermissions(Permission::whereIn('id',$d['permission_ids']??[])->get());Activity::record('created','users','Created user '.$u->email,[],['role'=>$d['role'],'direct_permissions'=>Permission::whereIn('id',$d['permission_ids']??[])->pluck('name')->all()]);return redirect()->route('users.index')->with('success','User created.');}
 public function edit(User $user){abort_if($user->hasRole('Super Admin'),403,'The Super Admin account is protected.');return view('users.form',['user'=>$user,'roles'=>Role::where('name','!=','Super Admin')->get(),'permissions'=>Permission::orderBy('name')->get()]);}
 public function update(Request $r,User $user){abort_if($user->hasRole('Super Admin'),403,'The Super Admin account is protected.');$d=$r->validate(['name'=>'required|string|max:190','email'=>'required|email|unique:users,email,'.$user->id,'password'=>'nullable|string|min:10|confirmed','role'=>'required|exists:roles,name','permission_ids'=>'nullable|array','permission_ids.*'=>'exists:permissions,id']);$oldRole=$user->getRoleNames()->first();$user->update(['name'=>$d['name'],'email'=>$d['email']]+(!empty($d['password'])?['password'=>Hash::make($d['password'])]:[]));$user->syncRoles([$d['role']]);$oldDirect=$user->getDirectPermissions()->pluck('name')->all();$user->syncPermissions(Permission::whereIn('id',$d['permission_ids']??[])->get());Activity::record('updated','users','Updated user '.$user->email,['role'=>$oldRole,'direct_permissions'=>$oldDirect],['role'=>$d['role'],'direct_permissions'=>Permission::whereIn('id',$d['permission_ids']??[])->pluck('name')->all()]);return redirect()->route('users.index')->with('success','User updated.');}
 public function destroy(User $user){abort_if($user->hasRole('Super Admin'),403,'The Super Admin account is protected.');abort_if($user->id===auth()->id(),403,'You cannot deactivate your own account.');$user->update(['is_active'=>false]);Activity::record('deactivated','users','Deactivated user '.$user->email);return back()->with('success','User deactivated.');}
}
